package com.gtnhvr.gui.settings.categories.controls;

import com.gtnhvr.gui.VRSettingsScreen;
import com.gtnhvr.gui.settings.OptionWidget;
import com.gtnhvr.gui.settings.OptionWidgetPosition;
import com.gtnhvr.gui.settings.VROptionsSet;
import com.gtnhvr.settings.VRClientSettings;
import me.eigenraven.lwjgl3ify.api.Lwjgl3Aware;
import net.minecraft.client.resources.I18n;
import org.lwjgl.input.Keyboard;

/**
 * Remapping page for the two extra virtual controller buttons generated by shoulder gestures.
 *
 * Click a binding button, then press the keyboard key whose Minecraft/Forge/mod action
 * should be emitted by that gesture. This intentionally does not inspect or guess mod names.
 */
@Lwjgl3Aware
public final class VRSettingsShoulderGestures extends VROptionsSet {
    private static final int CAPTURE_NONE = 0;
    private static final int CAPTURE_RIGHT_TO_LEFT = 1;
    private static final int CAPTURE_LEFT_TO_RIGHT = 2;

    private int captureTarget = CAPTURE_NONE;

    public VRSettingsShoulderGestures(VRSettingsScreen screen, VROptionsSet previousSet) {
        super(screen, previousSet);
    }

    @Override
    protected void buildWidgets() {
        widgets.add(new OptionWidget.ToggleWidget(
                OptionWidgetPosition.CENTER, 0,
                I18n.format("gtnhvr.controls.shoulder.master"),
                () -> VRClientSettings.shoulderGesturesEnabled,
                value -> {
                    VRClientSettings.shoulderGesturesEnabled = value;
                    VRClientSettings.save();
                },
                I18n.format("gtnhvr.controls.shoulder.master.tooltip")
        ));

        widgets.add(new OptionWidget.ButtonWidget(
                OptionWidgetPosition.CENTER, 1,
                () -> captureTarget == CAPTURE_RIGHT_TO_LEFT
                        ? I18n.format("gtnhvr.controls.shoulder.press_key")
                        : I18n.format("gtnhvr.controls.shoulder.right_to_left") + ": "
                            + getKeyName(VRClientSettings.shoulderRightToLeftKeyCode),
                () -> captureTarget = CAPTURE_RIGHT_TO_LEFT,
                I18n.format("gtnhvr.controls.shoulder.right_to_left.tooltip")
                        + "\n\n" + I18n.format("gtnhvr.controls.shoulder.capture_instructions")
        ));

        widgets.add(new OptionWidget.ToggleWidget(
                OptionWidgetPosition.LEFT, 3,
                I18n.format("gtnhvr.controls.shoulder.right_to_left.enabled"),
                () -> VRClientSettings.shoulderRightToLeftEnabled,
                value -> {
                    VRClientSettings.shoulderRightToLeftEnabled = value;
                    VRClientSettings.save();
                },
                I18n.format("gtnhvr.controls.shoulder.right_to_left.enabled.tooltip")
        ));

        widgets.add(new OptionWidget.ButtonWidget(
                OptionWidgetPosition.CENTER, 2,
                () -> captureTarget == CAPTURE_LEFT_TO_RIGHT
                        ? I18n.format("gtnhvr.controls.shoulder.press_key")
                        : I18n.format("gtnhvr.controls.shoulder.left_to_right") + ": "
                            + getKeyName(VRClientSettings.shoulderLeftToRightKeyCode),
                () -> captureTarget = CAPTURE_LEFT_TO_RIGHT,
                I18n.format("gtnhvr.controls.shoulder.left_to_right.tooltip")
                        + "\n\n" + I18n.format("gtnhvr.controls.shoulder.capture_instructions")
        ));

        widgets.add(new OptionWidget.ToggleWidget(
                OptionWidgetPosition.RIGHT, 3,
                I18n.format("gtnhvr.controls.shoulder.left_to_right.enabled"),
                () -> VRClientSettings.shoulderLeftToRightEnabled,
                value -> {
                    VRClientSettings.shoulderLeftToRightEnabled = value;
                    VRClientSettings.save();
                },
                I18n.format("gtnhvr.controls.shoulder.left_to_right.enabled.tooltip")
        ));

        widgets.add(new OptionWidget.SliderWidget(
                OptionWidgetPosition.LEFT, 4,
                I18n.format("gtnhvr.controls.shoulder.distance"),
                0.10F, 0.45F, 0.01F,
                () -> VRClientSettings.shoulderGestureDistance,
                value -> {
                    VRClientSettings.shoulderGestureDistance = value;
                    VRClientSettings.save();
                },
                value -> String.format("%.0f cm", value * 100.0F),
                I18n.format("gtnhvr.controls.shoulder.distance.tooltip")
        ));

        widgets.add(new OptionWidget.SliderWidget(
                OptionWidgetPosition.RIGHT, 4,
                I18n.format("gtnhvr.controls.shoulder.hold"),
                0.25F, 2.50F, 0.25F,
                () -> VRClientSettings.shoulderGestureHoldSeconds,
                value -> {
                    VRClientSettings.shoulderGestureHoldSeconds = value;
                    VRClientSettings.save();
                },
                value -> String.format("%.2f s", value),
                I18n.format("gtnhvr.controls.shoulder.hold.tooltip")
        ));
    }

    private static String getKeyName(int keyCode) {
        if (keyCode <= 0) {
            return I18n.format("gtnhvr.controls.shoulder.unassigned");
        }
        String keyName = Keyboard.getKeyName(keyCode);
        return keyName == null || keyName.isEmpty() ? "KEY " + keyCode : keyName;
    }

    @Override
    public boolean handleKeyTyped(char typedChar, int keyCode) {
        if (captureTarget == CAPTURE_NONE) return false;

        if (keyCode == Keyboard.KEY_ESCAPE) {
            captureTarget = CAPTURE_NONE;
            return true;
        }

        // Backspace/Delete explicitly clear a binding; Escape cancels capture.
        if (keyCode == Keyboard.KEY_BACK || keyCode == Keyboard.KEY_DELETE) {
            if (captureTarget == CAPTURE_RIGHT_TO_LEFT) {
                VRClientSettings.shoulderRightToLeftKeyCode = 0;
            } else {
                VRClientSettings.shoulderLeftToRightKeyCode = 0;
            }
            captureTarget = CAPTURE_NONE;
            VRClientSettings.save();
            return true;
        }

        if (keyCode > 0) {
            if (captureTarget == CAPTURE_RIGHT_TO_LEFT) {
                VRClientSettings.shoulderRightToLeftKeyCode = keyCode;
            } else {
                VRClientSettings.shoulderLeftToRightKeyCode = keyCode;
            }
            captureTarget = CAPTURE_NONE;
            VRClientSettings.save();
        }
        return true;
    }
}
